 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                x, y = stack.pop()
                cells.append((x, y))
                for dx, dy in ((1,0), (-1,0), (0,1), (0,-1)):
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == 2 and (nx, ny) not in seen:
                        seen.add((nx, ny))
                        stack.append((nx, ny))
            objects.append((min(y for _, y in cells), cells))
    objects.sort(key=lambda item: item[0])
    # Each successive object left-to-right alternates 2,8. In the examples,
    # the leftmost is 8 exactly when the number of objects is odd.
    first_is_8 = len(objects) % 2 == 1
    for i, (_, cells) in enumerate(objects):
        if (i % 2 == 0) == first_is_8:
            for r, c in cells:
                out[r][c] = 8
    return out

